    "Y tabl hon yw'r ffordd bysellfwrdd i'r fatrics: dewiswch effaith ac ymdrech ar gyfer pob eitem a bydd yn symud yn y fatrics ac yn y rhestrau Nawr / Nesaf / Yn ddiweddarach.",
